void to_json(Json& j, const Animator& v) {
    j = Json::object();
    j["clip"] = v.clip;
    j["playing"] = v.playing;
    j["loop"] = v.loop;
    j["speed"] = v.speed;
    j["time"] = v.time;
    j["finished"] = v.finished;
    j["fade"] = v.fade;
    j["fade_time"] = v.fade_time;
    j["from_clip"] = v.from_clip;
    j["from_time"] = v.from_time;
    j["layers"] = Json::array();
    for (const auto& x : v.layers) { Json e; to_json(e, x); j["layers"].push_back(std::move(e)); }
    j["root_motion"] = v.root_motion;
    j["root"] = v.root;
    vec_to_json(j["root_delta"], v.root_delta);
    j["root_rotation"] = v.root_rotation;
    j["root_delta_yaw"] = v.root_delta_yaw;
}

void from_json(const Json& j, Animator& v) {
    scalar_from_json(j, "clip", v.clip);
    scalar_from_json(j, "playing", v.playing);
    scalar_from_json(j, "loop", v.loop);
    scalar_from_json(j, "speed", v.speed);
    scalar_from_json(j, "time", v.time);
    scalar_from_json(j, "finished", v.finished);
    scalar_from_json(j, "fade", v.fade);
    scalar_from_json(j, "fade_time", v.fade_time);
    scalar_from_json(j, "from_clip", v.from_clip);
    scalar_from_json(j, "from_time", v.from_time);
    if (j.is_object() && j.contains("layers") && j["layers"].is_array()) {
        v.layers.clear();
        for (const Json& e : j["layers"]) { AnimationLayer x; from_json(e, x); v.layers.push_back(std::move(x)); }
    }
    scalar_from_json(j, "root_motion", v.root_motion);
    scalar_from_json(j, "root", v.root);
    if (j.is_object() && j.contains("root_delta")) vec_from_json(j["root_delta"], v.root_delta);
    scalar_from_json(j, "root_rotation", v.root_rotation);
    scalar_from_json(j, "root_delta_yaw", v.root_delta_yaw);
}

void hash_component(StateHasherRef& h, const Animator& v) {
    h.str(v.clip);
    h.u8(v.playing ? 1 : 0);
    h.u8(v.loop ? 1 : 0);
    h.f32(v.speed);
    h.f32(v.time);
    h.u8(v.finished ? 1 : 0);
    h.f32(v.fade);
    h.f32(v.fade_time);
    h.str(v.from_clip);
    h.f32(v.from_time);
    h.i64(static_cast<std::int64_t>(v.layers.size()));
    for (const auto& x : v.layers) hash_record(h, x);
    h.i64(static_cast<std::int64_t>(v.root_motion));
    h.str(v.root);
    h.f32(v.root_delta.x);
    h.f32(v.root_delta.y);
    h.f32(v.root_delta.z);
    h.u8(v.root_rotation ? 1 : 0);
    h.f32(v.root_delta_yaw);
}

std::size_t numeric_span(Animator& v, std::string_view path, float** out) {
    (void)v;
    if (path == "speed") { *out = &v.speed; return 1; }
    if (path == "time") { *out = &v.time; return 1; }
    if (path == "fade") { *out = &v.fade; return 1; }
    if (path == "fade_time") { *out = &v.fade_time; return 1; }
    if (path == "from_time") { *out = &v.from_time; return 1; }
    if (path.starts_with("layers.")) {
        std::string_view rest = path.substr(7);
        std::size_t index = 0;
        if (list_index(rest, index) && index < v.layers.size()) return numeric_span(v.layers[index], rest, out);
    }
    if (path == "root_delta") { *out = &v.root_delta.x; return 3; }
    if (path == "root_delta.x") { *out = &v.root_delta.x; return 1; }
    if (path == "root_delta.y") { *out = &v.root_delta.y; return 1; }
    if (path == "root_delta.z") { *out = &v.root_delta.z; return 1; }
    if (path == "root_delta_yaw") { *out = &v.root_delta_yaw; return 1; }
    return 0;
}

